typedef unsigned int size_t;
#define NULL 0

class stringx {
    void *data;
public:
    stringx(const char *);
    stringx(const stringx &);
    ~stringx();
};

class color32 {
public:
    unsigned int value;
    int get_alpha() const { return value >> 24; }
};

class Font {
public:
    enum HORIZJUST { HORIZJUST_LEFT, HORIZJUST_CENTER, HORIZJUST_RIGHT };
    enum VERTJUST { VERTJUST_TOP, VERTJUST_CENTER, VERTJUST_BOTTOM };
};

class TextString {
public:
    TextString(Font *, stringx, float, float, int, float,
               Font::HORIZJUST, Font::VERTJUST, color32);
    virtual ~TextString();
    virtual void Update(float);
    virtual void Draw();
    virtual void setHJustify(Font::HORIZJUST);
    virtual void setVJustify(Font::VERTJUST);
    virtual void setFont(Font *);
    virtual void setButtonScale(float);
};

class FEManager {
public:
    char padding[0x100];
    Font font_info;
    char padding2[0x100];
    color32 col_info_g;
};

class FEMenu;

class FEMenuSystem {
public:
    char padding[0x78];
    FEManager *manager;
};

class FEMenuEntry;

enum {
    FEMENU_HAS_COLOR = 0x004,
    FEMENU_HAS_COLOR_HIGH = 0x008,
    FEMENU_HAS_COLOR_HIGH_ALT = 0x010,
    FEMENU_USE_SCALE = 0x080
};

class FEMenu {
protected:
    static const int HF_UP = 0x001;
    static const int HF_DOWN = 0x002;
    static const int HF_SELECT = 0x010;
    static const int HF_RESUME = 0x040;
public:
    int center_x, center_y, num_entries, dy, half, menu_num;
    bool init;
    char init_padding[3];
    stringx font_filename;
    color32 color, color_high, color_high_alt;
    float scale, scale_high;
    int max_vis_entries, flags;
    FEMenuEntry *entries, *first_vis_entry, *last_vis_entry, *highlighted;
    FEMenuSystem *system;
    FEMenu *back;
    int back_num;
protected:
    FEMenu *submenus, *active, *parent;
    TextString *helpText;
    int helpFlags;
public:
    FEMenu *next_sub;
    virtual ~FEMenu();
    virtual void setBack(FEMenu *, int = 1);
    virtual void setHigh(FEMenuEntry *, bool = true);
    virtual void setVis(FEMenuEntry *);
    virtual void Add(FEMenuEntry *);
    virtual void Init();
    virtual void Load(bool);
    virtual void Load();
    virtual void Draw();
    virtual void DrawTop();
    virtual void UpdateInScene();
    virtual void Update(float);
    virtual void HighlightDefault();
    virtual void OnActivate();
    virtual void OnActivate(int);
    virtual void OnUnactivate(FEMenu *);
    virtual void OnSelect(int);
    virtual void OnStart(int);
    virtual void OnUp(int);
    virtual void OnDown(int);
    virtual void OnLeft(int);
    virtual void OnRight(int);
    virtual void OnCross(int);
    virtual void OnTriangle(int);
    virtual void OnSquare(int);
    virtual void OnCircle(int);
    virtual void OnL1(int);
    virtual void OnR1(int);
    virtual void OnL2(int);
    virtual void OnR2(int);
    virtual void OnAnyButtonPress(int, int);
    virtual void OnButtonRelease(int, int);
    virtual void SetAllScale(float);
    virtual void MakeActive(FEMenu *, bool = true);
    virtual void SetHelpText(int);
protected:
    virtual void cons(FEMenuSystem *, int, int, color32, color32, color32,
                      float, float, int, int);
};

void *operator new(size_t, unsigned int, const char *, int);
#define NEW new(0, (const char *)0x004C3438, 0)

void FEMenu::cons(FEMenuSystem* s, int x, int y, color32 c, color32 ch, color32 cha, float sc, float sch, int mve, int flg)
{
	entries = NULL;
	first_vis_entry = NULL;
	last_vis_entry = NULL;
	highlighted = NULL;
	back = NULL;
	system = s;
	flags = flg;

	helpText = NEW TextString(&system->manager->font_info, "", 320, 365, 800, 0.8f, Font::HORIZJUST_CENTER, Font::VERTJUST_CENTER, system->manager->col_info_g);
	helpText->setButtonScale(1.0f);
	SetHelpText(HF_UP | HF_DOWN | HF_SELECT | HF_RESUME);

	// scrolling will be set true if more than max_vis_entries
	//	scrolling = false;
	//	wrap = false;
	center_x = x;
	center_y = y;
	num_entries = 0;
	dy = 28;
	half = 0;
	init = false;
	//	has_color = hc;
	//	has_color_high = hch;

	if (c.get_alpha() == 0) flags = (flags & !FEMENU_HAS_COLOR);
	else
	{
		flags |= FEMENU_HAS_COLOR;
		color = c;
	}
	if (ch.get_alpha() == 0) flags = (flags & !FEMENU_HAS_COLOR_HIGH);
	else
	{
		flags |= FEMENU_HAS_COLOR_HIGH;
		color_high = ch;
	}
	if (cha.get_alpha() == 0) flags = (flags & !FEMENU_HAS_COLOR_HIGH_ALT);
	else
	{
		flags |= FEMENU_HAS_COLOR_HIGH_ALT;
		color_high_alt = cha;
	}

	flags |= FEMENU_USE_SCALE;
	scale = sc;
	scale_high = sch;
	active = NULL;
	next_sub = NULL;
	parent = NULL;
	max_vis_entries = mve;
}
